

/*
  Minimal CSV loader — no library needed for a static, no-build site.
  Handles quoted fields (including embedded commas/newlines/escaped quotes),
  which is all real-world CSV parsing needs beyond a naive split(",").
*/

function escapeHtml(str) {
  return String(str == null ? "" : str)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

// Explicit opt-in for a cell that needs to render as a real link — CSV text
// (including the URL) is escaped here so nothing from a scraped/fetched
// source can inject markup; app.js checks for this shape before using
// innerHTML for a cell instead of plain escaped text.
function linkCell(url, label) {
  return { __html: `<a href="${escapeHtml(url)}" target="_blank" rel="noopener">${escapeHtml(label)}</a>`, text: label };
}

// Prefixes a cell with a small "UNCONFIRMED" badge whenever a row's
// source_reliability marks it as unofficial corroboration (e.g. a news
// aggregator report, not yet matched against the actual government order)
// — per the build brief, these rows must never render identically to an
// official-source row. Rows with no source_reliability field (or an
// official one) render exactly like a normal cell.
function badgeCell(label, isUnofficial) {
  // Per-row provenance is documented in the feature's Source note; the inline
  // "UNCONFIRMED" badge was removed as it read as clutter and truncated cells.
  return { __html: escapeHtml(label), text: label };
}

function parseCSV(text) {
  const rows = [];
  let row = [];
  let field = "";
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; }
        else { inQuotes = false; }
      } else {
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ',') {
      row.push(field); field = "";
    } else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); field = "";
      if (row.length > 1 || row[0] !== "") rows.push(row);
      row = [];
    } else {
      field += c;
    }
  }
  if (field !== "" || row.length) { row.push(field); rows.push(row); }
  if (!rows.length) return [];
  const headers = rows[0];
  return rows.slice(1).map(r => {
    const obj = {};
    headers.forEach((h, idx) => { obj[h] = r[idx] !== undefined ? r[idx] : ""; });
    return obj;
  });
}

