// Standalone build: all data is already embedded above, so "cache" is just
// the embedded object itself — this also satisfies app.js's `csvCache[...]`
// checks (undefined here would throw a ReferenceError inside renderDataBlock).
const csvCache = EMBEDDED_CSV_DATA;
const jsonCache = EMBEDDED_JSON_DATA;

async function loadCSV(filename) {
  return EMBEDDED_CSV_DATA[filename] || [];
}

async function loadJSON(filename) {
  return EMBEDDED_JSON_DATA[filename] || {};
}

